1|import Combine
2|import Foundation
3|
4|@MainActor
5|final class LoginViewModel: ObservableObject {
6|    @Published var username: String = ""
7|    @Published var password: String = ""
8|    @Published var isLoading: Bool = false
9|    @Published var loginError: String?
10|    @Published var isLoggedIn: Bool = false
11|
12|    func login() async {
13|        guard !username.isEmpty, !password.isEmpty else {
14|            loginError = "Please enter both username and password"
15|            return
16|        }
17|
18|        isLoading = true
19|        defer { isLoading = false }
20|
21|        let failure = ProcessInfo.processInfo.arguments.contains("--ui_test_login_failure")
22|        try? await Task.sleep(nanoseconds: 300_000_000)
23|
24|        if failure {
25|            loginError = "Invalid credentials"
26|        } else {
27|            loginError = nil
28|            isLoggedIn = false
29|        }
30|    }
31|}
